function iconImg(key, size, cls) {
  return `<img src="data:image/png;base64,${ICONS[key] || ""}" style="width:${size}px;height:${size}px;display:block;" class="${cls || ""}" alt="" />`;
}

function applyStaticIcons() {
  document.querySelectorAll("[data-icon]").forEach((el) => {
    const key = el.getAttribute("data-icon");
    const size = el.getAttribute("data-icon-size") || 15;
    el.innerHTML = iconImg(key, size);
  });
}
