/* ============================================================
   HELPERS
   ============================================================ */
function $(sel) { return document.querySelector(sel); }
function $all(sel) { return document.querySelectorAll(sel); }
function escapeHtml(s) {
  return String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}
function showToast(msg, type) {
  const stack = $("#toastStack");
  const el = document.createElement("div");
  el.className = "toast" + (type ? " " + type : "");
  el.textContent = msg;
  stack.appendChild(el);
  requestAnimationFrame(() => el.classList.add("show"));
  setTimeout(() => { el.classList.remove("show"); setTimeout(() => el.remove(), 250); }, 3000);
}
function fmtDateTime(iso) {
  if (!iso) return "-";
  const d = new Date(iso);
  return d.toLocaleDateString("th-TH", { day: "2-digit", month: "2-digit", year: "2-digit", timeZone: "Asia/Bangkok" }) + " " +
         d.toLocaleTimeString("th-TH", { hour: "2-digit", minute: "2-digit", timeZone: "Asia/Bangkok" });
}
function fmtTime(iso) {
  if (!iso) return "-";
  return new Date(iso).toLocaleTimeString("th-TH", { hour: "2-digit", minute: "2-digit", timeZone: "Asia/Bangkok" });
}
function stockStatus(bal) {
  if (!bal) return "ok";
  if (bal.qty <= 0) return "out";
  if (bal.qty <= bal.min_qty) return "low";
  return "ok";
}
function totalQty(part) {
  return (part.stock_balances || []).reduce((sum, b) => sum + (b.qty || 0), 0);
}
function primaryBalance(part) {
  return (part.stock_balances || [])[0] || null;
}
function L(obj, field) {
  if (!obj) return "";
  const suffix = state.lang === "en" ? "_en" : state.lang === "zh" ? "_zh" : "";
  if (suffix && obj[field + suffix]) return obj[field + suffix];
  return obj[field] || "";
}

function txPartName(tx) {
  const live = state.parts.find((p) => p.id === tx.part_id);
  return live ? L(live, "part_name") : (tx.part_name || "-");
}

function initialsOf(name) {
  return (name || "?").trim().slice(0, 2).toUpperCase();
}
function avatarHtml(url, name, size) {
  size = size || 28;
  if (url) return `<img class="avatar" style="width:${size}px;height:${size}px;" src="${escapeHtml(url)}" alt="" />`;
  return `<div class="avatar" style="width:${size}px;height:${size}px;background:var(--icon-blue-pale);color:var(--accent-text);font-size:${Math.round(size*0.36)}px;">${escapeHtml(initialsOf(name))}</div>`;
}

