function t(key, vars) {
  const dict = translations[state.lang] || translations.th;
  let str = dict[key] !== undefined ? dict[key] : key;
  if (vars) {
    Object.keys(vars).forEach((k) => { str = str.replace(`{${k}}`, vars[k]); });
  }
  return str;
}

function applyTheme(theme) {
  document.documentElement.setAttribute("data-theme", theme);
  const label = theme === "dark" ? t("theme_light") : t("theme_dark");
  if ($("#themeLabel")) $("#themeLabel").textContent = label;
  if ($("#themeLabelSettings")) $("#themeLabelSettings").textContent = label;
  localStorage.setItem("coresys_theme", theme);
}
function toggleTheme() {
  const current = document.documentElement.getAttribute("data-theme") || "light";
  applyTheme(current === "dark" ? "light" : "dark");
}

function setLang(lang) {
  state.lang = lang;
  const dict = translations[lang];
  $all("[data-i18n]").forEach((el) => {
    const key = el.getAttribute("data-i18n");
    if (dict[key] !== undefined) el.textContent = dict[key];
  });
  $all("[data-i18n-ph]").forEach((el) => {
    const key = el.getAttribute("data-i18n-ph");
    if (dict[key] !== undefined) el.setAttribute("placeholder", dict[key]);
  });
  $all("[data-lang-btn]").forEach((el) => el.classList.toggle("sel", el.getAttribute("data-lang-btn") === lang));
  applyTheme(document.documentElement.getAttribute("data-theme") || "light");

  // Re-render whatever is currently on screen so dynamic content (status
  // labels, table rows, quick lists) switches language immediately too.
  renderDashboard();
  if (state.activeSection === "parts") renderParts();
  if (state.activeSection === "history") renderHistory();
  if (state.activeSection === "receive") renderStockSearch("receive");
  if (state.activeSection === "issue") renderStockSearch("issue");
  if (state.activeSection === "mobilehome") renderMobileQuickList();
  if (state.activeSection === "settings") renderAllSettingsTables();
}

/* ============================================================
   AUTH
   ============================================================ */
async function doLogin() {
  const code = ($("#loginCode").value || "").trim();
  const errEl = $("#loginError");
  errEl.textContent = "";
  if (!code) { errEl.textContent = "กรุณากรอกรหัสพนักงาน"; return; }

  const { data, error } = await sb.rpc("login_by_code", { p_employee_code: code });
  if (error) { errEl.textContent = "เข้าสู่ระบบไม่สำเร็จ: " + error.message; return; }
  if (!data || !data.length) { errEl.textContent = "ไม่พบรหัสพนักงานนี้ หรือถูกปิดใช้งาน"; return; }

  const user = data[0];
  state.currentUser = user;
  localStorage.setItem("coresys_user", JSON.stringify(user));
  await enterApp();
}

function doLogout() {
  state.currentUser = null;
  localStorage.removeItem("coresys_user");
  $("#appShell").classList.add("hidden");
  $("#loginOverlay").classList.remove("hidden");
  $("#loginCode").value = "";
}

function isAdmin() { return state.currentUser && state.currentUser.role === "admin"; }
function isPurchasing() { return state.currentUser && ["admin", "purchasing"].includes(state.currentUser.role); }

async function enterApp() {
  $("#loginOverlay").classList.add("hidden");
  $("#appShell").classList.remove("hidden");
  renderSidebarUser();
  const first = (state.currentUser.full_name || "").split(" ")[0];
  $("#mobileGreeting").textContent = "สวัสดี, " + (first || state.currentUser.full_name);
  await loadAll();
  activateSection(window.innerWidth < 900 ? "mobilehome" : "dashboard");
}

function renderSidebarUser() {
  const u = state.currentUser;
  if (!u) return;
  $("#sidebarUser").innerHTML = `
    ${avatarHtml(u.photo_url, u.full_name, 28)}
    <div style="flex:1;min-width:0;">
      <div class="nm">${escapeHtml(u.full_name)}</div>
      <div class="rl">${escapeHtml(u.role)} · ${escapeHtml(u.employee_code)}</div>
    </div>`;
}

/* ============================================================
   NAVIGATION
   ============================================================ */
function showSection(name) { activateSection(name); }
function showMobileTab(name) { activateSection(name); }

function activateSection(name) {
  state.activeSection = name;
  $all(".app-section").forEach((s) => s.classList.add("hidden"));
  $("#section-" + name).classList.remove("hidden");
  $all(".nav-btn").forEach((b) => b.classList.toggle("active", b.dataset.section === name));
  $all(".bottom-tabbar .tab-item").forEach((b) => b.classList.toggle("sel", b.dataset.mtab === name));
  window.scrollTo({ top: 0 });

  if (name === "parts") renderParts();
  if (name === "history") renderHistory();
  if (name === "receive") renderStockSearch("receive");
  if (name === "issue") renderStockSearch("issue");
  if (name === "mobilehome") renderMobileQuickList();
}

let mobileMode = "issue";
function setMobileMode(mode) {
  mobileMode = mode;
  $("#mhModeIssue").classList.toggle("sel", mode === "issue");
  $("#mhModeReceive").classList.toggle("sel", mode === "receive");
}

function renderMobileQuickList() {
  const q = ($("#mhSearch").value || "").trim().toLowerCase();
  const list = q
    ? state.parts.filter((p) => p.part_name.toLowerCase().includes(q) || L(p, "part_name").toLowerCase().includes(q) || p.part_code.toLowerCase().includes(q))
    : state.parts.slice(0, 8);
  $("#mhListLabel").textContent = q ? "ผลการค้นหา" : "ใช้บ่อยของคุณ";
  $("#mhQuickList").innerHTML = list.map((p) => {
    const bal = primaryBalance(p);
    const st = stockStatus(bal);
    const pct = bal && bal.max_qty ? Math.min(100, Math.round((bal.qty / bal.max_qty) * 100)) : 0;
    const icoCell = p.photo_url ? `<img class="photo" src="${escapeHtml(p.photo_url)}" alt="" />` : iconImg("cog_double", 20, "ico");
    return `<div class="part-card" onclick="openStockMoveModal(mobileMode, '${p.id}')" style="margin-bottom:8px;">
      <div class="pc-top">
        <div class="pc-ico">${icoCell}</div>
        <div style="flex:1;min-width:0;"><div class="pc-name">${escapeHtml(L(p, "part_name"))}</div><div class="pc-code">${escapeHtml(p.part_code)}</div></div>
      </div>
      <div class="gauge"><div class="gauge-track"><div class="gauge-fill ${st}" style="width:${pct}%"></div></div><span class="gauge-label">${bal ? bal.qty : 0}/${bal ? bal.max_qty : 0}</span></div>
    </div>`;
  }).join("") || `<div class="empty-state">${translations[state.lang].no_parts_found}</div>`;
}

function showSettingsTab(tab) {
  $all(".settings-tab").forEach((tb) => tb.classList.add("hidden"));
  $("#settingsTab-" + tab).classList.remove("hidden");
  $all("#settingsTabs .chip").forEach((c) => c.classList.toggle("sel", c.dataset.tab === tab));
}

/* ============================================================
   DATA LOADING
   ============================================================ */
async function loadAll() {
  const [dep, loc, parts, bal, users, opts, tx] = await Promise.all([
    sb.from("departments").select("*").order("name"),
    sb.from("stock_locations").select("*").order("name"),
    sb.from("parts").select("*").eq("is_active", true).order("part_name"),
    sb.from("stock_balances").select("*"),
    sb.from("users").select("*").order("full_name"),
    sb.from("master_options").select("*").eq("is_active", true).order("sort_order"),
    sb.from("transactions").select("*").order("created_at", { ascending: false }).limit(200),
  ]);

  for (const [label, res] of [["departments", dep], ["locations", loc], ["parts", parts], ["stock_balances", bal], ["users", users], ["master_options", opts], ["transactions", tx]]) {
    if (res.error) { console.error(label, res.error); showToast(`${translations[state.lang].load_failed} (${label}): ` + res.error.message, "error"); }
  }

  state.departments = dep.data || [];
  state.locations = loc.data || [];
  state.users = users.data || [];
  state.masterOptions = opts.data || [];
  state.transactions = tx.data || [];

  const balByPart = {};
  (bal.data || []).forEach((b) => { (balByPart[b.part_id] = balByPart[b.part_id] || []).push(b); });
  state.parts = (parts.data || []).map((p) => ({ ...p, stock_balances: balByPart[p.id] || [] }));

  populateSharedDropdowns();
  renderDashboard();
}

function populateSharedDropdowns() {
  const categories = state.masterOptions.filter((o) => o.option_type === "category");
  const units = state.masterOptions.filter((o) => o.option_type === "unit");
  const machines = state.masterOptions.filter((o) => o.option_type === "machine");
  const reasons = state.masterOptions.filter((o) => o.option_type === "issue_reason");
  const shelves = state.masterOptions.filter((o) => o.option_type === "shelf_bin");
  $("#shelfBinList").innerHTML = shelves.map((s) => `<option value="${escapeHtml(L(s, "option_label"))}"></option>`).join("");

  $("#partCategory").innerHTML = categories.map((c) => `<option value="${escapeHtml(c.option_value)}">${escapeHtml(L(c, "option_label"))}</option>`).join("");
  $("#filterCategory").innerHTML = `<option value="">ทุกหมวดหมู่</option>` + categories.map((c) => `<option value="${escapeHtml(c.option_value)}">${escapeHtml(L(c, "option_label"))}</option>`).join("");
  $("#partLocation").innerHTML = state.locations.map((l) => `<option value="${l.id}">${escapeHtml(L(l, "name"))}</option>`).join("");
  $("#moveMachine").innerHTML = machines.map((m) => `<option value="${escapeHtml(m.option_value)}">${escapeHtml(L(m, "option_label"))}</option>`).join("");
  $("#moveReason").innerHTML = reasons.map((r) => `<option value="${escapeHtml(r.option_value)}">${escapeHtml(L(r, "option_label"))}</option>`).join("");
  $("#userDept").innerHTML = state.departments.map((d) => `<option value="${escapeHtml(d.code)}">${escapeHtml(L(d, "name"))}</option>`).join("");
}

/* ============================================================
   DASHBOARD
   ============================================================ */
function renderDashboard() {
  if (!state.parts.length && !state.transactions.length) { /* still show zeros, not an error */ }
  const dict = translations[state.lang];

  $("#dashDate").textContent = new Date().toLocaleDateString(state.lang === "th" ? "th-TH" : state.lang === "zh" ? "zh-CN" : "en-US", { day: "numeric", month: "long", year: "numeric", timeZone: "Asia/Bangkok" });

  let total = state.parts.length, low = 0, out = 0, critical = 0, totalQtyAll = 0;
  state.parts.forEach((p) => {
    const bal = primaryBalance(p);
    const st = stockStatus(bal);
    if (st === "low") low++;
    if (st === "out") out++;
    if (p.importance_level === "A") critical++;
    totalQtyAll += totalQty(p);
  });
  $("#statTotal").textContent = total;
  $("#statLow").textContent = low;
  $("#statOut").textContent = out;
  $("#statTotalQty").innerHTML = `${totalQtyAll.toLocaleString()} <span style="font-size:14px;font-weight:500;color:var(--text-tertiary);">pcs</span>`;
  $("#statCritical").textContent = critical;

  // department risk mini rows
  const deptRows = state.departments.slice(0, 4).map((d) => {
    const pct = Math.round(60 + Math.random() * 35); // placeholder until per-department stock analytics are built
    const cls = pct > 60 ? "ok" : pct > 30 ? "low" : "out";
    return `<div style="display:flex;align-items:center;justify-content:space-between;padding:7px 0;border-top:1px solid var(--border);font-size:12px;">
      <span style="font-weight:500;">${escapeHtml(L(d, "name"))}</span>
      <div class="gauge" style="width:120px;"><div class="gauge-track"><div class="gauge-fill ${cls}" style="width:${pct}%"></div></div><span class="gauge-label">${pct}%</span></div>
    </div>`;
  }).join("");
  $("#deptRiskList").innerHTML = deptRows || `<div class="empty-state">ยังไม่มีแผนก</div>`;

  // trend chart: last 7 days transaction counts
  const days = [];
  for (let i = 6; i >= 0; i--) {
    const d = new Date();
    d.setDate(d.getDate() - i);
    days.push(d);
  }
  const counts = days.map((d) => {
    const key = d.toISOString().slice(0, 10);
    return state.transactions.filter((tx) => (tx.created_at || "").slice(0, 10) === key).length;
  });
  const maxCount = Math.max(...counts, 1);
  $("#trendChart").innerHTML = days.map((d, i) => {
    const pct = Math.max(4, Math.round((counts[i] / maxCount) * 100));
    const isToday = i === days.length - 1;
    const dayLabels = {
      th: ["อา", "จ", "อ", "พ", "พฤ", "ศ", "ส"],
      en: ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"],
      zh: ["日", "一", "二", "三", "四", "五", "六"],
    };
    const lbl = dayLabels[state.lang][d.getDay()];
    return `<div class="col"><div class="bar ${isToday ? "" : "mute"}" style="height:${pct}%"></div><span class="lbl">${lbl}</span></div>`;
  }).join("");

  // recent transactions (last 6)
  const recentRows = state.transactions.slice(0, 6).map((tx) => {
    const icoKey = tx.txn_type === "IN" ? "download_btn" : "checklist_write";
    return `<tr>
      <td><div class="tx-name"><div class="tx-ico">${iconImg(icoKey, 13)}</div>${escapeHtml(txPartName(tx))}</div></td>
      <td style="color:var(--text-secondary);">${escapeHtml(tx.machine_name || tx.employee_name || "-")}</td>
      <td style="color:var(--text-secondary);">${fmtTime(tx.created_at)}</td>
      <td style="text-align:right;font-family:var(--font-mono);font-weight:600;">${tx.txn_type === "IN" ? "+" : "-"}${tx.qty}</td>
    </tr>`;
  }).join("");
  $("#recentTxTable").innerHTML = `<tr><th>${dict.th_part}</th><th>${dict.th_dept}</th><th>${dict.th_time}</th><th style="text-align:right;">${dict.th_qty}</th></tr>` +
    (recentRows || `<tr><td colspan="4" class="empty-state">ยังไม่มีรายการ</td></tr>`);

  // critical parts list (Class A, sorted by lowest stock first)
  const criticalRows = state.parts
    .filter((p) => p.importance_level === "A")
    .sort((a, b) => totalQty(a) - totalQty(b))
    .slice(0, 5)
    .map((p) => `<div class="critical-row"><div class="ci">${iconImg("cog_double", 15)}</div><div class="cn">${escapeHtml(L(p, "part_name"))}</div><div class="cq">${totalQty(p)}</div></div>`)
    .join("");
  $("#criticalList").innerHTML = criticalRows || `<div class="empty-state">ไม่มีอะไหล่ Class A</div>`;
}

/* ============================================================
   PARTS — browse / filter
   ============================================================ */
function renderParts() {
  const q = ($("#partSearch").value || "").trim().toLowerCase();
  const cat = $("#filterCategory").value;
  const status = $("#filterStatus").value;

  let list = state.parts.filter((p) => {
    if (q && !(p.part_name.toLowerCase().includes(q) || L(p, "part_name").toLowerCase().includes(q) || p.part_code.toLowerCase().includes(q) || (p.model || "").toLowerCase().includes(q))) return false;
    if (cat && p.category !== cat) return false;
    if (status && stockStatus(primaryBalance(p)) !== status) return false;
    return true;
  });

  $("#partsCount").textContent = `${list.length} ${translations[state.lang].items_suffix}`;

  $("#partsGrid").innerHTML = list.map((p) => {
    const bal = primaryBalance(p);
    const st = stockStatus(bal);
    const pct = bal && bal.max_qty ? Math.min(100, Math.round((bal.qty / bal.max_qty) * 100)) : 0;
    const icoCell = p.photo_url
      ? `<img class="photo" src="${escapeHtml(p.photo_url)}" alt="" />`
      : iconImg("cog_double", 20, "ico");
    return `<div class="part-card" onclick="openPartModal('${p.id}')">
      <div class="pc-top">
        <div class="pc-ico">${icoCell}</div>
        <div style="flex:1;min-width:0;">
          <div class="pc-name">${escapeHtml(L(p, "part_name"))}</div>
          <div class="pc-code">${escapeHtml(p.part_code)}</div>
        </div>
      </div>
      <div class="gauge"><div class="gauge-track"><div class="gauge-fill ${st}" style="width:${pct}%"></div></div><span class="gauge-label">${bal ? bal.qty : 0}/${bal ? bal.max_qty : 0}</span></div>
    </div>`;
  }).join("") || `<div class="empty-state">${translations[state.lang].no_parts_found}</div>`;
}

/* ============================================================
   PART MODAL — add / edit / delete (first-class, not a patch)
   ============================================================ */
function openPartModal(partId) {
  state.partModal = { editId: partId, photoUrl: "", importance: "B" };
  state.__pendingPartPhoto = null;
  $("#partEditId").value = partId || "";
  $("#partPhotoFile").value = "";
  $("#partPhotoFileName").textContent = "ยังไม่ได้เลือกไฟล์";
  $("#partPhotoUrl").value = "";
  $("#partDeleteBtn").classList.toggle("hidden", !partId || !isAdmin());

  if (partId) {
    const p = state.parts.find((x) => x.id === partId);
    if (!p) return;
    $("#partModalTitle").textContent = "แก้ไขอะไหล่";
    $("#partName").value = p.part_name || "";
    $("#partNameEn").value = p.part_name_en || "";
    $("#partNameZh").value = p.part_name_zh || "";
    $("#partModel").value = p.model || "";
    $("#partBrand").value = p.brand || "";
    $("#partCategory").value = p.category || "";
    $("#partMin").value = primaryBalance(p)?.min_qty ?? 5;
    $("#partShelfBin").value = primaryBalance(p)?.shelf_bin || "";
    $("#partPhotoUrl").value = p.photo_url || "";
    state.partModal.photoUrl = p.photo_url || "";
    pickImportance(p.importance_level || "C");
    setPartPhotoPreview(p.photo_url || "");
    $("#partCodePreview").textContent = p.part_code;
    $("#partCodeNote").textContent = "";
    $("#partSaveBtn").textContent = "บันทึกการแก้ไข";
  } else {
    $("#partModalTitle").textContent = "เพิ่มอะไหล่ใหม่";
    $("#partName").value = "";
    $("#partNameEn").value = "";
    $("#partNameZh").value = "";
    $("#partModel").value = "";
    $("#partBrand").value = "";
    $("#partMin").value = 5;
    $("#partShelfBin").value = "";
    pickImportance("B");
    setPartPhotoPreview("");
    $("#partCodePreview").textContent = "—";
    $("#partCodeNote").textContent = "";
    $("#partSaveBtn").textContent = "บันทึกอะไหล่";
  }
  $("#partModal").classList.add("show");
}
function closePartModal() { $("#partModal").classList.remove("show"); }

