  const existing = state.parts.find((p) => (p.model || "").toLowerCase() === model.toLowerCase());
  $("#partCodePreview").textContent = data;
  $("#partCodeNote").textContent = existing ? `พบอะไหล่รุ่นนี้ในระบบแล้ว (${L(existing, "part_name")})` : "ระบบสร้างให้อัตโนมัติ";
