/* ============================================================
   IMAGE UPLOAD → Supabase Storage
   ============================================================ */
function compressImageFile(file, maxSize, quality) {
  maxSize = maxSize || 700; quality = quality || 0.8;
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        let w = img.width, h = img.height;
        if (w > h && w > maxSize) { h = Math.round(h * (maxSize / w)); w = maxSize; }
        else if (h > maxSize) { w = Math.round(w * (maxSize / h)); h = maxSize; }
        const canvas = document.createElement("canvas");
        canvas.width = w; canvas.height = h;
        canvas.getContext("2d").drawImage(img, 0, 0, w, h);
        canvas.toBlob((blob) => resolve(blob), "image/jpeg", quality);
      };
      img.onerror = reject;
      img.src = e.target.result;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

async function uploadToStorage(bucket, blob, previewId, hiddenId) {
  const path = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}.jpg`;
  const { error } = await sb.storage.from(bucket).upload(path, blob, { contentType: "image/jpeg" });
  if (error) { showToast(translations[state.lang].upload_failed + ": " + error.message, "error"); return; }
  const { data } = sb.storage.from(bucket).getPublicUrl(path);
  const url = data.publicUrl;
  $("#" + hiddenId).value = url;
  const prev = $("#" + previewId);
  prev.className = prev.className.replace(" empty", "");
  prev.innerHTML = `<img src="${escapeHtml(url)}" alt="" />`;
  return url;
}

function bindPhotoInput(fileId, bucket, previewId, hiddenId) {
  const nameEl = $("#" + fileId + "Name");
  $("#" + fileId).addEventListener("change", async (e) => {
    const file = e.target.files[0];
    if (!file) { if (nameEl) nameEl.textContent = translations[state.lang].no_file; return; }
    if (!file.type.startsWith("image/")) return showToast(translations[state.lang].select_image_only, "error");
    if (nameEl) nameEl.textContent = file.name;
    const blob = await compressImageFile(file, bucket === "user-photos" ? 400 : 800, 0.82);
    if (bucket === "user-photos") {
      state.__pendingUserPhoto = blob;
    } else {
      state.__pendingPartPhoto = blob;
    }
    const url = URL.createObjectURL(blob);
    const prev = $("#" + previewId);
    prev.className = prev.className.replace(" empty", "");
    prev.innerHTML = `<img src="${url}" alt="" />`;
  });
}

/* ============================================================
   STOCK MOVE (receive / issue) — shared modal
   ============================================================ */
function renderStockSearch(mode) {
  const q = ($("#" + mode + "Search").value || "").trim().toLowerCase();
  const list = q
    ? state.parts.filter((p) => p.part_name.toLowerCase().includes(q) || L(p, "part_name").toLowerCase().includes(q) || p.part_code.toLowerCase().includes(q))
    : state.parts.slice(0, 8);

  const cards = list.map((p) => {
    const bal = primaryBalance(p);
    const st = stockStatus(bal);
    const pct = bal && bal.max_qty ? Math.min(100, Math.round((bal.qty / bal.max_qty) * 100)) : 0;
    return `<div class="part-card" onclick="openStockMoveModal('${mode}','${p.id}')">
      <div class="pc-top">
        <div class="pc-ico">${p.photo_url ? `<img class="photo" src="${escapeHtml(p.photo_url)}" alt="" />` : iconImg("cog_double", 20, "ico")}</div>
        <div style="flex:1;min-width:0;"><div class="pc-name">${escapeHtml(L(p, "part_name"))}</div><div class="pc-code">${escapeHtml(p.part_code)}</div></div>
      </div>
      <div class="gauge"><div class="gauge-track"><div class="gauge-fill ${st}" style="width:${pct}%"></div></div><span class="gauge-label">${bal ? bal.qty : 0}/${bal ? bal.max_qty : 0}</span></div>
    </div>`;
  }).join("");

  $("#" + mode + "Results").innerHTML = cards
    ? `<div class="parts-grid">${cards}</div>`
    : `<div class="empty-state">${translations[state.lang].no_parts_found}</div>`;
}

function openStockMoveModal(mode, partId) {
  const p = state.parts.find((x) => x.id === partId);
  const bal = primaryBalance(p);
  if (!bal) return showToast(translations[state.lang].no_location_set, "error");

  state.moveModal = { mode, part: p, balance: bal, qty: 1 };
  $("#stockMoveTitle").textContent = mode === "receive" ? translations[state.lang].receive_title : translations[state.lang].issue_title;
  $("#stockMovePartInfo").textContent = `${L(p, "part_name")} · ${p.part_code}`;
  $("#issueOnlyFields").classList.toggle("hidden", mode !== "issue");
  $("#receiveOnlyFields").classList.toggle("hidden", mode !== "receive");
  updateMoveGauge();
  $("#moveQtyVal").textContent = 1;
  $("#moveSupplier").value = "";
  $("#moveDoc").value = "";
  $("#moveRemark").value = "";
  $("#stockMoveModal").classList.add("show");
}
function closeStockMoveModal() { $("#stockMoveModal").classList.remove("show"); }

function updateMoveGauge() {
  const { balance } = state.moveModal;
  const pct = balance.max_qty ? Math.min(100, Math.round((balance.qty / balance.max_qty) * 100)) : 0;
  const st = stockStatus(balance);
  $("#stockMoveGaugeFill").className = "gauge-fill " + st;
  $("#stockMoveGaugeFill").style.width = pct + "%";
  $("#stockMoveGaugeLabel").textContent = `${balance.qty} / ${balance.max_qty} pcs`;
}

function stepMoveQty(d) {
  const next = state.moveModal.qty + d;
  if (next < 1) return;
  if (state.moveModal.mode === "issue" && next > state.moveModal.balance.qty) return showToast(translations[state.lang].qty_exceeded, "error");
  state.moveModal.qty = next;
  $("#moveQtyVal").textContent = next;
}

async function confirmStockMove() {
  const { mode, balance, qty } = state.moveModal;
  const u = state.currentUser;
  const payload = {
    p_stock_balance_id: balance.id,
    p_txn_type: mode === "receive" ? "IN" : "OUT",
    p_qty: qty,
    p_employee_name: u.full_name,
    p_employee_id: u.employee_code,
    p_machine_name: mode === "issue" ? $("#moveMachine").value : "",
    p_document_no: mode === "receive" ? $("#moveDoc").value : "",
    p_reason: mode === "issue" ? $("#moveReason").value : "",
    p_remark: mode === "receive" ? $("#moveSupplier").value + (($("#moveRemark").value) ? " · " + $("#moveRemark").value : "") : $("#moveRemark").value,
  };
  const { data, error } = await sb.rpc("stock_move", payload);
  if (error) return showToast(translations[state.lang].txn_failed + ": " + error.message, "error");

  const d = translations[state.lang];
  showToast(`${mode === "receive" ? d.txn_receive_done : d.txn_issue_done} · ${d.remaining_label} ${data.after_qty} pcs`, "success");
  closeStockMoveModal();

  if (mode === "issue") {
    notifyLineIssue({
      partName: data.part_name,
      partCode: data.part_code,
      model: state.moveModal.part?.model || "-",
      employeeName: u.full_name,
      department: u.department_code || "-",
      qty,
      unit: state.moveModal.part?.unit || "pcs",
      machineName: $("#moveMachine").value,
      remainingQty: data.after_qty,
    });
  }

  await loadAll();
  renderStockSearch(mode);
}

function notifyLineIssue(details) {
  sb.functions.invoke("line-notify-issue", { body: details }).catch((err) => {
    console.warn("LINE notify failed (transaction already saved):", err);
  });
}

