function pickExportChip(el) {
  const g = el.getAttribute("data-g");
  state.exportChoice[g] = el.getAttribute("data-v");
  $all(`.chip[data-g="${g}"]`).forEach((c) => c.classList.toggle("sel", c === el));
}
function openExport() { $("#exportModal").classList.add("show"); }
function closeExport() { $("#exportModal").classList.remove("show"); }
function confirmExport() {
  const { scope, lang } = state.exportChoice;
  const headers = {
    th: { part_code: "รหัสอะไหล่", part_name: "ชื่ออะไหล่", model: "รุ่น", brand: "ยี่ห้อ", qty: "คงเหลือ", min: "ขั้นต่ำ", importance: "ความสำคัญ", date: "วันที่", type: "ประเภท", employee: "ผู้ทำรายการ" },
    en: { part_code: "Part Code", part_name: "Part Name", model: "Model", brand: "Brand", qty: "Qty", min: "Min", importance: "Importance", date: "Date", type: "Type", employee: "Employee" },
    zh: { part_code: "备件编号", part_name: "备件名称", model: "型号", brand: "品牌", qty: "库存", min: "最低库存", importance: "重要等级", date: "日期", type: "类型", employee: "经办人" },
  }[lang];

  let rows, filename;
  if (scope === "parts") {
    rows = state.parts.map((p) => {
      const bal = primaryBalance(p);
      return {
        [headers.part_code]: p.part_code, [headers.part_name]: L(p, "part_name"), [headers.model]: p.model,
        [headers.brand]: p.brand, [headers.qty]: bal ? bal.qty : 0, [headers.min]: bal ? bal.min_qty : 0,
        [headers.importance]: p.importance_level,
      };
    });
    filename = "parts_export.xlsx";
  } else {
    rows = state.transactions.map((tx) => ({
      [headers.date]: fmtDateTime(tx.created_at), [headers.type]: tx.txn_type, [headers.part_code]: tx.part_code,
      [headers.part_name]: txPartName(tx), [headers.qty]: tx.qty, [headers.employee]: tx.employee_name,
    }));
    filename = "history_export.xlsx";
  }

  const ws = XLSX.utils.json_to_sheet(rows);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Sheet1");
  XLSX.writeFile(wb, filename);
  closeExport();
  showToast(translations[state.lang].export_success + ": " + filename, "success");
}

/* ============================================================
   BARCODE SCANNER
   ============================================================ */
let scannerControls = null;
async function openScanner(mode) {
  $("#scannerModal").classList.add("show");
  try {
    const codeReader = new ZXingBrowser.BrowserMultiFormatReader();
    scannerControls = await codeReader.decodeFromVideoDevice(undefined, "scannerVideo", (result) => {
      if (result) {
        const code = result.getText();
        const p = state.parts.find((x) => x.barcode === code || x.part_code === code);
        closeScanner();
        if (p) openStockMoveModal(mode, p.id);
        else showToast(translations[state.lang].barcode_not_found, "error");
      }
    });
  } catch (err) {
    console.error(err);
    showToast(translations[state.lang].camera_failed + ": " + err.message, "error");
  }
}
function closeScanner() {
  $("#scannerModal").classList.remove("show");
  if (scannerControls) { scannerControls.stop(); scannerControls = null; }
}

/* ============================================================
   INIT
   ============================================================ */
function renderAllSettingsTables() {
  renderDeptTable();
  renderLocTable();
  renderUserTable();
  renderOptTable();
}

document.addEventListener("DOMContentLoaded", async () => {
  applyStaticIcons();
  const currentTheme = document.documentElement.getAttribute("data-theme") || "light";
  applyTheme(currentTheme);
  bindPhotoInput("partPhotoFile", "part-photos", "partPhotoPreview", "partPhotoUrl");
  bindPhotoInput("userPhotoFile", "user-photos", "userPhotoPreview", "userPhotoUrl");

  $("#loginCode").addEventListener("keydown", (e) => { if (e.key === "Enter") doLogin(); });

  const saved = localStorage.getItem("coresys_user");
  if (saved) {
    try {
      state.currentUser = JSON.parse(saved);
      await enterApp();
    } catch (e) { localStorage.removeItem("coresys_user"); }
  }
});

const _origLoadAll = loadAll;
loadAll = async function () {
  await _origLoadAll();
  renderAllSettingsTables();
};
